import * as THREE from 'three';
import './style.css';

const $ = (s, root=document) => root.querySelector(s);
const ui = $('#ui');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x070916);
scene.fog = new THREE.FogExp2(0x080a18, 0.0028);
const camera = new THREE.PerspectiveCamera(62, innerWidth/innerHeight, .1, 900);
const renderer = new THREE.WebGLRenderer({antialias:false, powerPreference:'high-performance'});
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
$('#game').appendChild(renderer.domElement);
const clock = new THREE.Clock();
const hemi = new THREE.HemisphereLight(0x6a83c7,0x14111f,1.05); scene.add(hemi);
const moon = new THREE.DirectionalLight(0x8599ff,1.25); moon.position.set(-80,120,40); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-120;moon.shadow.camera.right=120;moon.shadow.camera.top=120;moon.shadow.camera.bottom=-120;scene.add(moon);
const ambientGlow = new THREE.PointLight(0x6a39d9,95,160,2); ambientGlow.position.set(-9,12,-4);scene.add(ambientGlow);
const mat=(color,rough=.7,metal=0,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal,emissive,emissiveIntensity:ei});
const boxGeo=new THREE.BoxGeometry(1,1,1), sphereGeo=new THREE.SphereGeometry(1,12,8), cylGeo=new THREE.CylinderGeometry(1,1,1,10);
function box(parent,x,y,z,sx,sy,sz,material,cast=false,receive=true){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=cast;m.receiveShadow=receive;parent.add(m);return m;}
function cylinder(parent,x,y,z,r,h,material,rotZ=0,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,segments),material);m.position.set(x,y,z);m.rotation.z=rotZ;parent.add(m);return m;}
function glow(color,intensity=1){return new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:intensity,roughness:.35,metalness:.1});}
const mats={road:mat(0x171a25,.9),side:mat(0x353546),ground:mat(0x10121d),lane:mat(0xc5c1bb,.7,0,0x656273,.12),dark:mat(0x0b0c14),glass:mat(0x111927,.22,.52),white:mat(0xe6e5ef,.5,.15),purple:glow(0xa34bff,2.4),cyan:glow(0x26ddf3,2.3),gold:glow(0xffbe66,1.7),red:glow(0xff245e,2)};
const world={size:480, blocks:[], lights:[], traffic:[], pedestrians:[], buildings:[]};
// Endless-looking ground and a carefully laid, navigable 6 x 6 downtown grid.
box(scene,0,-.8,0,world.size,1,world.size,mat(0x080a13,1));
const districtDefs=[[-120,-120,'OLD QUARTER'],[0,-130,'NEON CORE'],[120,-110,'FINANCIAL BAY'],[-125,80,'RESIDENTIAL'],[0,105,'MARINA DRIVE'],[135,95,'SKYLINE EAST']];
const roads=[];
for(let v=-180;v<=180;v+=60){box(scene,v,.015,0,13,.08,world.size,mats.road);box(scene,0,.016,v,world.size,.08,13,mats.road);
  for(let k=-225;k<225;k+=12){box(scene,v,.07,k, .16,.015,4.2,mats.lane);box(scene,k,.07,v,4.2,.015,.16,mats.lane);}
  // Neon curb strips
  box(scene,v,.12,-240,13,.22,.35,mats.cyan);box(scene,240,.12,v,.35,.22,13,mats.purple);
}
// Block lots, streetside low-rise details, tall towers and emissive window grids.
const buildingMats=[0x182338,0x20243a,0x25263a,0x162c3b,0x252239,0x1b2b38].map(c=>mat(c,.48,.36));
const windowsA=glow(0xffd697,.7), windowsB=glow(0x80eaff,.65), windowsOff=mat(0x101724,.4,.15);
const windowInstances=[];
for(let bx=-150;bx<=150;bx+=60)for(let bz=-150;bz<=150;bz+=60){
  const cx=bx+30,cz=bz+30;
  if(Math.abs(cx)<30&&Math.abs(cz)<30)continue;
  const count=3+(Math.abs(bx*bz)%3), spacing=11.5;
  for(let n=0;n<count;n++){
    const x=cx+(n-(count-1)/2)*spacing, z=cz+((n%2)?8:-8);
    const w=8.5+(n%2)*2.5,d=9+(n%3)*1.5;
    const h=14+((Math.abs(Math.floor(x*7+z*3))%9)*6);
    const tower=(Math.abs(x)<74&&Math.abs(z)<74)||Math.abs(x)>115;
    const height=tower?h+35+(Math.abs(Math.floor(x+z))%7)*7:h;
    const base=box(scene,x,height/2,z,w,height,d,buildingMats[Math.abs(Math.floor(x*3+z))%buildingMats.length],true);
    base.userData.kind='building'; world.buildings.push(base);
    box(scene,x,height+.45,z,w+.7,.8,d+.7,mat(0x39435b,.45,.5));
    // crown and vertical accent strips
    if(height>45){box(scene,x,height+.95,z,w*.55,.2,d*.6,glow(n%2?0xa64aff:0x35dff5,1.5));box(scene,x-w*.47,height*.55,z,.15,height*.9,.2,glow(n%3?0x8d3fff:0x34dced,1.0));}
    for(let fy=5;fy<height-4;fy+=4.2){
      for(let fx=-w/2+1.1;fx<w/2-.5;fx+=2.1){
        if(Math.random()<.25)continue;
        let wm=Math.random()<.32?windowsB:windowsA;
        for(const [side,face] of [[1,'front'],[-1,'back']]){
          const win=box(scene,x+fx,fy,z+side*(d/2+.025),1.25,1.45,.055,wm);windowInstances.push(win);
        }
        if(Math.random()<.7)for(const side of [-1,1])box(scene,x+side*(w/2+.025),fy,z+fx, .055,1.45,1.25,wm);
      }
    }
    // Rooftop tanks and aerials make the skyline readable from the road.
    if(height>60){cylinder(scene,x+w*.22,height+2,z-d*.15,1.2,3,mat(0x424556,.5,.35));box(scene,x,height+5,z,.12,6,.12,mat(0x737487,.45,.6));}
  }
  // Each block gets a small storefront with a colored fascia.
  const shoph=5.8; box(scene,cx,shoph/2,cz+17,19,shoph,7,mat(0x252337,.65,.15),true);
  box(scene,cx,shoph-1,cz+13.35,17,.52,.1,glow((Math.floor(cx+cz)%2)?0xb34bff:0x20dff2,1.6));
  for(let j=0;j<3;j++)box(scene,cx-6+j*6,2.2,cz+13.25,4,3.8,.12,mat(0x172b3b,.18,.45,0x183a62,.6));
}
// Ground-level garage landmark; its open facade is visible from every approach.
const garage=new THREE.Group();garage.position.set(-8,0,0);scene.add(garage);
box(garage,0,5,0,24,10,19,mat(0x232333,.55,.3),true);
box(garage,0,2.35,9.7,18,4.7,.3,mat(0x080c14,.25,.5));
box(garage,0,7,9.68,20,.75,.35,mats.purple);box(garage,0,8.35,9.68,14,.12,.3,mats.cyan);
for(let y=2;y<7;y+=1.3)box(garage,0,y,9.9,17,.04,.05,glow(0x8f8c9c,.6));
box(garage,-11,11,0,2,2,2,mat(0x272b3a));
// Central neon tower, broad arterial and rooftop helipad.
const spire=box(scene,0,47,-62,21,94,21,mat(0x182337,.25,.6),true);box(scene,0,96,-62,8,7,8,mats.purple);box(scene,0,102,-62,.3,10,.3,mats.cyan);
for(let y=8;y<90;y+=8)box(scene,0,y,-51.1,18,.28,.2,glow(y%16?0x20dff2:0xb34bff,1.3));
// Rooftop mission marker.
const helipad=new THREE.Group();helipad.position.set(105,34,8);scene.add(helipad);box(helipad,0,0,0,26,1,22,mat(0x303141,.72,.25),false);cylinder(helipad,0,.65,0,8,.08,mats.cyan);box(helipad,0,.72,0,1.2,.1,10,mats.white);box(helipad,0,.72,0,10,.1,1.2,mats.white);

