input.content:
const carCatalog=[
 {id:'Vanta R',type:'SUPERCAR',price:0,color:0x9b59ff,speed:45,accel:25,handling:2.5,mass:1.0,shape:'low'},
 {id:'Apex GT',type:'TRACK COUPE',price:3200,color:0xe9e6ef,speed:56,accel:30,handling:2.8,mass:.86,shape:'sleek'},
 {id:'Titan X',type:'LUXURY SUV',price:5100,color:0x20cad8,speed:39,accel:19,handling:1.35,mass:1.55,shape:'suv'},
 {id:'Orion S',type:'GRAND TOURER',price:7400,color:0xf55378,speed:52,accel:26,handling:2.05,mass:1.13,shape:'gt'},
 {id:'Phantom 9',type:'HYPERSPORT',price:11000,color:0xffbd63,speed:68,accel:36,handling:2.35,mass:.92,shape:'hyper'}
];
const owned=new Set(['Vanta R']);
const keys={};
let playerMoney=850, selectedCar=carCatalog[0], mode='menu', vehicle=null, paused=false, garageOpen=false, speed=0, cameraYaw=0, cameraPitch=.12;
let missionIndex=0, missionProgress=0, dayTime=0.82, soundCtx=null, engineOsc=null;
const player={pos:new THREE.Vector3(-22,0,13),vel:new THREE.Vector3(),heading:0,walking:false,crouched:false};
const character=new THREE.Group();scene.add(character);
const skin=mat(0xb77f69,.82), jacket=mat(0x171927,.48,.12), pants=mat(0x242638,.7), shoe=mat(0x090b12,.55,.2), visor=mat(0xb76eff,.25,.5,0x681bff,.65);
const torso= new THREE.Group(); character.add(torso);
const torsoMesh=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.7,4,8),jacket);torsoMesh.position.y=1.28;torso.add(torsoMesh);
const head=new THREE.Mesh(new THREE.SphereGeometry(.27,12,10),skin);head.position.set(0,2.0,0);torso.add(head);
const face=new THREE.Mesh(new THREE.BoxGeometry(.37,.08,.08),visor);face.position.set(0,2.02,-.22);torso.add(face);
const limbGeo=new THREE.CapsuleGeometry(.13,.5,3,7);
function limb(parent,x,y,material){const pivot=new THREE.Group();pivot.position.set(x,y,0);parent.add(pivot);const mesh=new THREE.Mesh(limbGeo,material);mesh.position.y=-.37;pivot.add(mesh);return pivot;}
const legL=limb(torso,-.22,.95,pants),legR=limb(torso,.22,.95,pants),armL=limb(torso,-.52,1.63,jacket),armR=limb(torso,.52,1.63,jacket);
for(const leg of [legL,legR]){const foot=new THREE.Mesh(new THREE.BoxGeometry(.26,.12,.43),shoe);foot.position.set(0,-.7,-.08);leg.add(foot);}
// Soft pool lights and a tracked neon waypoint landmark.
const playerLamp=new THREE.PointLight(0x9a66ff,3.8,16,2);playerLamp.position.set(0,2.2,0);character.add(playerLamp);
const marker=new THREE.Group();scene.add(marker);const markerDisc=new THREE.Mesh(new THREE.TorusGeometry(2.2,.09,8,32),mats.cyan);markerDisc.rotation.x=Math.PI/2;marker.add(markerDisc);const markerBeam=new THREE.Mesh(new THREE.CylinderGeometry(.13,.85,4,12,1,true),new THREE.MeshBasicMaterial({color:0x59e8f4,transparent:true,opacity:.18,side:THREE.DoubleSide}));markerBeam.position.y=2;marker.add(markerBeam);
function createCar(def,paint=def.color){
 const g=new THREE.Group();g.userData={def,paint,speed:0,heading:0,owned:true,upgrades:{engine:0,handling:0}};
 const bodymat=mat(paint,.25,.65);const glassmat=mat(0x101b2b,.14,.58);const tiremat=mat(0x090a0d,.86,.05);const metal=mat(0x8e94a6,.23,.8);
 const suv=def.shape==='suv', low=def.shape==='low'||def.shape==='hyper', length=4.5,width=suv?2.05:1.92,height=suv?1.55:(low?.72:.92);
 box(g,0,.62,0,width,height,length,bodymat,true);
 // Sculpted nose and cabin silhouette, with unbranded original styling.
 box(g,0,.98,-.35,width*.82,.42,length*.48,bodymat,true);
 box(g,0,1.25,.25,width*.7,.58,length*.43,glassmat);
 box(g,0,1.56,.23,width*.64,.09,length*.38,bodymat);
 box(g,0,.76,-length*.5,.34,.1,.11,mats.dark);
 // Side skirts and colored pinstripe
 for(const s of [-1,1]){box(g,s*(width/2+.02),.39,0,.09,.18,length*.63,bodymat);box(g,s*(width/2+.07),.57,0,.035,.035,length*.75,glow(paint,1));}
 // Lights
 for(const s of [-1,1]){box(g,s*.62,.77,-length/2-.025,.48,.15,.07,mats.cyan);box(g,s*.66,.74,length/2+.03,.4,.14,.07,mats.red);}
 const wheels=[];
 for(const x of [-width*.53,width*.53])for(const z of [-length*.31,length*.31]){
   const wh=new THREE.Group();wh.position.set(x,.39,z);g.add(wh);const tire=new THREE.Mesh(new THREE.CylinderGeometry(.38,.38,.22,14),tiremat);tire.rotation.z=Math.PI/2;wh.add(tire);const rim=new THREE.Mesh(new THREE.CylinderGeometry(.23,.23,.232,8),metal);rim.rotation.z=Math.PI/2;wh.add(rim);for(let n=0;n<5;n++){const spoke=box(wh,0,0,0,.035,.38,.04,mat(0xb8bdcb,.3,.85));spoke.rotation.x=n*Math.PI/5;}
   if(z<0){wh.userData.steer=true;}wheels.push(wh);
 }
 g.userData.wheels=wheels;
 const headL=new THREE.SpotLight(0xa6eaff,25,48,.43,.45,1.1);headL.position.set(-.65,.85,-2.15);headL.target.position.set(-.65,.2,-12);g.add(headL,headL.target);
 const headR=headL.clone();headR.position.x=.65;headR.target.position.x=.65;g.add(headR,headR.target);
 g.userData.lamps=[headL,headR];return g;
}
function parkCar(def,x,z,heading=0){const car=createCar(def);car.position.set(x,0,z);car.rotation.y=heading;car.userData.heading=heading;scene.add(car);return car;}
const parkedCars=[];
carCatalog.forEach((c,i)=>{const a=parkCar(c,-20+i*4.5,29,Math.PI);parkedCars.push(a);});
// Decorative autonomous traffic follows long, looping arterial lanes.
const trafficDefs=[carCatalog[1],carCatalog[2],carCatalog[3],carCatalog[0]];
for(let i=0;i<9;i++){
 const def=trafficDefs[i%trafficDefs.length], car=createCar({...def,color:[0x283a54,0x713b76,0x3b5660,0x6a364d][i%4]});
 car.userData.ai=true;car.userData.route=(i%2===0)?-60:0;car.userData.aiSpeed=7+(i%4)*1.5;car.position.set(-210+i*47,0,(i%2===0)?-60:0);car.rotation.y=Math.PI/2;scene.add(car);world.traffic.push(car);
}
// Pedestrians: tiny articulated figures traverse sidewalks between lamp pools.
const npcMats=[mat(0x355470),mat(0x75516e),mat(0x456257),mat(0x77705a)];
for(let i=0;i<22;i++){
 const npc=new THREE.Group();const coat=npcMats[i%4];const body=new THREE.Mesh(new THREE.CapsuleGeometry(.19,.42,3,6),coat);body.position.y=.78;npc.add(body);const headN=new THREE.Mesh(new THREE.SphereGeometry(.13,8,6),skin);headN.position.y=1.25;npc.add(headN);
 npc.position.set(-170+Math.random()*340,0,(i%2?1:-1)*10+(Math.floor(Math.random()*7)*60));npc.userData={origin:npc.position.clone(),phase:Math.random()*7,speed:.7+Math.random()*.6,side:i%2?1:-1};scene.add(npc);world.pedestrians.push(npc);
}

const missionData=[
 {title:'THE FIRST ARRIVAL',desc:'Find the Central Garage and check in with the crew.',target:new THREE.Vector3(-8,0,0),reward:0,kind:'visit'},
 {title:'NIGHT SHIFT',desc:'Take a car to the violet checkpoint in the Neon Core.',target:new THREE.Vector3(-60,0,-120),reward:900,kind:'drive'},
 {title:'LAST-MILE',desc:'Collect the courier parcel in the Residential Quarter.',target:new THREE.Vector3(-120,0,60),reward:700,kind:'pickup'},
 {title:'LAST-MILE',desc:'Deliver the parcel to the Marina market before it cools.',target:new THREE.Vector3(120,0,-120),reward:900,kind:'drop'},
 {title:'A NEW MACHINE',desc:'Visit the Central Garage and purchase your first new ride.',target:new THREE.Vector3(-8,0,0),reward:0,kind:'buy'},
 {title:'OPEN ROAD',desc:'Cross into Skyline East and claim the district.',target:new THREE.Vector3(120,0,0),reward:1200,kind:'unlock'},
 {title:'AFTER HOURS',desc:'Hit all three race gates before the 70-second timer runs out.',target:new THREE.Vector3(60,0,-60),reward:2200,kind:'race',time:70}
];
let raceTime=0,raceGate=0, deliveryPicked=false, districtUnlocked=false, toastTimer=0, ambienceStarted=false;
const raceGates=[new THREE.Vector3(60,0,-60),new THREE.Vector3(180,0,60),new THREE.Vector3(60,0,180)];
function currentTarget(){if(missionIndex>=missionData.length)return null;return missionIndex===6?raceGates[raceGate]:missionData[missionIndex].target;}
function flashToast(title,sub=''){const el=$('.mission-toast');if(!el)return;el.innerHTML=`<div class="toast-title">${title}</div><div class="toast-reward">${sub}</div>`;el.classList.add('show');toastTimer=3.1;}
function startAudio(){if(ambienceStarted)return;ambienceStarted=true;try{soundCtx=new (window.AudioContext||window.webkitAudioContext)();const osc=soundCtx.createOscillator(),gain=soundCtx.createGain();osc.type='sawtooth';osc.frequency.value=42;gain.gain.value=.0001;osc.connect(gain);gain.connect(soundCtx.destination);osc.start();engineOsc={osc,gain};const low=soundCtx.createOscillator(),lg=soundCtx.createGain();low.type='sine';low.frequency.value=54;lg.gain.value=.015;low.connect(lg);lg.connect(soundCtx.destination);low.start();}catch(e){}}
function setEngineSound(v){if(engineOsc&&soundCtx){engineOsc.osc.frequency.setTargetAtTime(38+Math.abs(v)*1.5,soundCtx.currentTime,.12);engineOsc.gain.gain.setTargetAtTime(vehicle?Math.min(.035,.006+Math.abs(v)*.0003):.0001,soundCtx.currentTime,.18);}}
function beep(freq=520,duration=.12){if(!soundCtx)return;const o=soundCtx.createOscillator(),g=soundCtx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.055,soundCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,soundCtx.currentTime+duration);o.connect(g);g.connect(soundCtx.destination);o.start();o.stop(soundCtx.currentTime+duration);}
function updateMissionUI(){
 const mission=missionData[Math.min(missionIndex,missionData.length-1)];
 const card=$('.mission-card');if(!card)return;
 const isDone=missionIndex>=missionData.length;
 const title=isDone?'DISTRICT LEGEND':mission.title;
 let desc=isDone?'Neon District is yours. Keep exploring, collecting rides and chasing the next record.':mission.desc;
 if(missionIndex===6&&!isDone)desc=`Race gate ${raceGate+1} of 3 · ${Math.max(0,Math.ceil(raceTime))} seconds remaining.`;
 card.innerHTML=`<div class="label">${isDone?'ALL OBJECTIVES COMPLETE':`ACTIVE OBJECTIVE · 0${missionIndex+1} / 07`}</div><div class="mission-title">${title}</div><div class="mission-desc">${desc}</div><div class="mission-progress"><i style="width:${isDone?100:Math.min(96,missionProgress*100)}%"></i></div><div class="mission-step">${isDone?'FREE ROAM ENABLED':'NEON DISTRICT  /  '+(missionIndex<2?'CORE':missionIndex<4?'CITY':'EAST')}</div>`;
}
function completeMission(reward=0,title='OBJECTIVE COMPLETE'){
 if(reward){playerMoney+=reward;}
 flashToast(title,reward?`+ ¤${reward.toLocaleString()}  /  objective cleared`:'OBJECTIVE CLEARED');beep(740,.2);
 missionIndex++;missionProgress=0;raceGate=0;
 if(missionIndex===6)raceTime=70;
 updateMissionUI();updateMoney();
}
function updateMoney(){const el=$('.money-value');if(el)el.textContent=`¤ ${playerMoney.toLocaleString()}`;}
function setTargetPosition(){const t=currentTarget();if(!t){marker.visible=false;return;}marker.visible=true;marker.position.set(t.x,0.35,t.z);}
function checkObjective(){
 const m=missionData[missionIndex];if(!m)return;
 const p=vehicle?vehicle.position:player.pos;const d=Math.hypot(p.x-m.target.x,p.z-m.target.z);
 const driving=!!vehicle;
 if(m.kind==='visit'&&d<13){missionProgress=Math.min(1,1-d/13);if(!vehicle&&keys.e){completeMission(0,'WELCOME TO THE DISTRICT');keys.e=false;}}
 else if(m.kind==='drive'&&d<11&&driving){missionProgress=1;completeMission(m.reward,'NIGHT SHIFT COMPLETE');}
 else if(m.kind==='pickup'&&d<11&&driving){missionProgress=1;completeMission(m.reward,'PARCEL SECURED');}
 else if(m.kind==='drop'&&d<12&&driving){missionProgress=1;completeMission(m.reward,'DELIVERY COMPLETE');}
 else if(m.kind==='buy'&&d<15&&!vehicle){missionProgress=.5;if(keys.e){openGarage();keys.e=false;}}
 else if(m.kind==='unlock'&&d<15){missionProgress=Math.min(1,1-d/15);if(keys.e){districtUnlocked=true;completeMission(m.reward,'SKYLINE EAST UNLOCKED');keys.e=false;}}
 if(m.kind==='race'){
   raceTime-=clock.getDelta?0:0;
   const gate=raceGates[raceGate];const gd=Math.hypot(p.x-gate.x,p.z-gate.z);
   if(gd<13&&driving){raceGate++;missionProgress=raceGate/3;beep(600+raceGate*100,.14);if(raceGate>=3)completeMission(m.reward,'RACE WON · NEW RECORD');else{setTargetPosition();updateMissionUI();}}
 }
}
function initUI(){
 ui.innerHTML=`<div class="screen" id="title-screen"><div class="menu-copy"><div class="eyebrow">A CITY THAT NEVER SLEEPS · 2049</div><div class="brand">NEON<span>DISTRICT</span></div><div class="subtitle">The night is yours to take. Find your first crew, make the streets your own, and build a legend one mile at a time.</div><div class="menu-actions"><button class="btn primary" data-action="play">ENTER THE CITY&nbsp; ↗</button><button class="btn" data-action="settings">SETTINGS</button></div><div class="menu-note">OPEN WORLD · STREET RACING · YOUR OWN RULES</div></div></div>
 <div class="game-hud" hidden><div class="topbar"><div><div class="hud-brand">NEON <span>DISTRICT</span></div><div class="district">NEON CORE · 23:48</div></div><div class="money"><small>AVAILABLE CREDITS</small><span class="money-value">¤ 850</span></div></div><button class="icon-btn settings-btn" data-action="pause">Ⅱ&nbsp; PAUSE</button><div class="mission-card"></div><div class="minimap"><canvas width="284" height="284"></canvas></div><div class="map-caption">DISTRICT RADAR</div><div class="prompt"><b>E</b> &nbsp; INTERACT</div><div class="controls-hint"><b>W A S D</b> MOVE / DRIVE &nbsp; <b>SHIFT</b> SPRINT<br><b>SPACE</b> JUMP &nbsp; <b>C</b> CROUCH &nbsp; <b>E</b> ENTER / INTERACT &nbsp; <b>F</b> EXIT</div><div class="speed-wrap"><div class="speed">000 <small>KM/H</small></div><div class="car-name">ON FOOT</div><div class="gear">WALK · CITY EXPLORER</div></div><div class="mission-toast"></div><div class="touch-controls"><div class="touch-stick" data-stick>MOVE</div><div class="touch-action secondary" data-key="Space">JUMP</div><div class="touch-action" data-key="e">INTERACT</div></div></div><div class="modal-root"></div>`;
 updateMissionUI();
}
function showSettings(){const root=$('.modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">PREFERENCES</div><h2>Settings</h2></div><button class="close" data-action="close-modal">✕</button></div><div class="settings-row"><span>Night exposure</span><input type="range" min=".65" max="1.7" step=".05" value="1.15" data-setting="exposure"></div><div class="settings-row"><span>Master ambience</span><input type="range" min="0" max=".05" step=".002" value=".015" data-setting="volume"></div><div class="settings-row"><span>Shadows</span><input type="checkbox" checked data-setting="shadows"></div><p>WASD to move / drive · Shift to sprint · Space to jump · C to crouch · E interact / enter · F exit · Esc pause. Mobile controls are available on touch screens.</p><button class="btn primary" data-action="close-modal">DONE</button></div></div>`;}
function showPause(){if(paused)return;paused=true;const root=$('.modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">NEON CORE · SESSION PAUSED</div><h2>Take a breath.</h2></div><button class="close" data-action="resume">✕</button></div><p>Your city, your pace. The streets will be right here.</p><div class="menu-actions"><button class="btn primary" data-action="resume">BACK TO THE CITY</button><button class="btn" data-action="missions">OBJECTIVES</button><button class="btn" data-action="settings">SETTINGS</button></div></div></div>`;}
function showMissions(){const root=$('.modal-root');const rows=missionData.map((m,i)=>`<div class="mission-row"><div class="mission-num">0${i+1}</div><div><strong>${m.title}</strong><small>${m.desc}</small></div><div class="lock">${i<missionIndex?'✓':i===missionIndex?'ACTIVE':'LOCKED'}</div></div>`).join('');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">PROGRESS LOG</div><h2>Street objectives</h2></div><button class="close" data-action="resume">✕</button></div><div class="mission-list">${rows}</div><button class="btn primary" style="margin-top:20px" data-action="resume">BACK TO THE CITY</button></div></div>`;}

function openGarage(){
 if(garageOpen)return;garageOpen=true;paused=true;const root=$('.modal-root');
 const cards=carCatalog.map(c=>{const has=owned.has(c.id);return `<article class="car-card ${selectedCar.id===c.id?'selected':''}" style="--swatch:#${c.color.toString(16).padStart(6,'0')}"><div class="car-swatch"></div><h3>${c.id}</h3><div class="price">${has?'OWNED':`¤ ${c.price.toLocaleString()} · ${c.type}`}</div><div class="stat-line">TOP SPEED ${c.speed*4} KM/H<br>HANDLING ${'▰'.repeat(Math.round(c.handling))}${'▱'.repeat(3-Math.round(c.handling))}</div><button class="btn ${has?'':'primary'}" data-action="${has?'select-car':'buy-car'}" data-car="${c.id}">${has?(selectedCar.id===c.id?'SELECTED':'TAKE THIS RIDE'):'PURCHASE'}</button></article>`;}).join('');
 const upgrades=vehicle?vehicle.userData.upgrades:{engine:0,handling:0};
 root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><div class="eyebrow">CENTRAL GARAGE · NEON CORE</div><h2>Make it yours.</h2><p>Buy original rides, tune the setup, and take your favorite into the night.</p></div><button class="close" data-action="close-garage">✕</button></div><div class="car-grid">${cards}</div><div class="garage-tools"><button class="btn" data-action="upgrade-engine">ENGINE UPGRADE · ¤ 800 (${upgrades.engine||0}/3)</button><button class="btn" data-action="upgrade-handling">HANDLING KIT · ¤ 650 (${upgrades.handling||0}/3)</button><label class="btn" style="display:flex;align-items:center;gap:8px">PAINT <input class="color-input" type="color" value="#${selectedCar.color.toString(16).padStart(6,'0')}" data-setting="paint"></label><button class="btn" data-action="wheels">${vehicle?.userData.wheelStyle?'WHEEL SET · ON':'WHEEL SET · ¤ 400'}</button></div><p>Performance upgrades apply to the active car. Paint and wheel options update your selected vehicle instantly.</p></div></div>`;
}
function closeGarage(){garageOpen=false;paused=false;$('.modal-root').innerHTML='';}
function refreshGarage(){if(garageOpen)openGarage();}
function buyCar(id){const c=carCatalog.find(a=>a.id===id);if(!c)return;if(owned.has(id)){selectedCar=c;flashToast(`${id.toUpperCase()} SELECTED`,'Ready for the open road.');refreshGarage();return;}if(playerMoney<c.price){flashToast('NOT ENOUGH CREDITS',`Need ¤ ${(c.price-playerMoney).toLocaleString()} more`);beep(170,.2);return;}playerMoney-=c.price;owned.add(id);selectedCar=c;updateMoney();if(missionIndex===4){missionIndex++;missionProgress=0;completeMission(0,'FIRST RIDE PURCHASED');}else flashToast('NEW RIDE ACQUIRED',`${id} · garage collection updated`);beep(820,.2);refreshGarage();}
function nearestParked(){let best=null,dist=8;for(const c of parkedCars){if(c===vehicle)continue;const d=c.position.distanceTo(player.pos);if(d<dist){best=c;dist=d;}}return best;}
function enterVehicle(car){if(!car)return;vehicle=car;selectedCar=carCatalog.find(c=>c.id===car.userData.def.id)||selectedCar;car.userData.ai=false;character.visible=false;car.userData.speed=0;player.pos.copy(car.position);player.heading=car.rotation.y;beep(440,.1);updatePrompt();}
function exitVehicle(){if(!vehicle)return;player.pos.copy(vehicle.position);player.heading=vehicle.rotation.y;player.pos.x+=Math.cos(player.heading)*2.5;player.pos.z-=Math.sin(player.heading)*2.5;vehicle=null;character.position.copy(player.pos);character.visible=true;speed=0;beep(350,.12);updatePrompt();}
function updatePrompt(){const prompt=$('.prompt');if(!prompt)return;let text='';if(vehicle)text='<b>F</b> &nbsp; EXIT VEHICLE';else if(nearestParked())text='<b>E</b> &nbsp; ENTER VEHICLE';else if(Math.hypot(player.pos.x+8,player.pos.z)<13)text='<b>E</b> &nbsp; CENTRAL GARAGE';else if(missionIndex===5&&Math.hypot(player.pos.x-120,player.pos.z)<15)text='<b>E</b> &nbsp; UNLOCK SKYLINE EAST';else text='<b>W A S D</b> &nbsp; EXPLORE';prompt.innerHTML=text;}
function handleInteract(){
 if(vehicle){if(keys.f){exitVehicle();keys.f=false;}return;}
 if(missionIndex===0&&Math.hypot(player.pos.x+8,player.pos.z)<13){completeMission(0,'WELCOME TO NEON DISTRICT');keys.e=false;return;}
 if(missionIndex===4&&Math.hypot(player.pos.x+8,player.pos.z)<16){openGarage();keys.e=false;return;}
 if(missionIndex===5&&Math.hypot(player.pos.x-120,player.pos.z)<15){districtUnlocked=true;completeMission(missionData[5].reward,'SKYLINE EAST UNLOCKED');keys.e=false;return;}
 const car=nearestParked();if(car){enterVehicle(car);keys.e=false;return;}
 if(Math.hypot(player.pos.x+8,player.pos.z)<16){openGarage();keys.e=false;return;}
}
function applyUpgrade(type){if(!vehicle){flashToast('BRING A CAR INTO THE GARAGE','Performance upgrades apply to your active ride.');return;}const ups=vehicle.userData.upgrades;if(ups[type]>=3){flashToast('MAXIMUM TUNE REACHED');return;}const cost=type==='engine'?800:650;if(playerMoney<cost){flashToast('NOT ENOUGH CREDITS',`Need ¤ ${(cost-playerMoney).toLocaleString()} more`);return;}playerMoney-=cost;ups[type]++;if(type==='engine'){vehicle.userData.def={...vehicle.userData.def,speed:vehicle.userData.def.speed+6,accel:vehicle.userData.def.accel+4};}else vehicle.userData.def={...vehicle.userData.def,handling:vehicle.userData.def.handling+.38};updateMoney();flashToast('UPGRADE INSTALLED',`${type.toUpperCase()} · performance increased`);refreshGarage();}
function setPaint(value){const hex=parseInt(value.slice(1),16);selectedCar.color=hex;for(const c of parkedCars)if(c.userData.def.id===selectedCar.id){c.traverse(o=>{if(o.isMesh&&o.material?.metalness>.5&&o.material.emissiveIntensity===0)o.material.color.setHex(hex);});}if(vehicle?.userData.def.id===selectedCar.id)vehicle.traverse(o=>{if(o.isMesh&&o.material?.metalness>.5&&o.material.emissiveIntensity===0)o.material.color.setHex(hex);});}
function setWheelStyle(){if(playerMoney<400){flashToast('NOT ENOUGH CREDITS','Wheel set costs ¤ 400.');return;}if(vehicle?.userData.wheelStyle){flashToast('WHEELS ALREADY INSTALLED');return;}playerMoney-=400;updateMoney();if(vehicle){vehicle.userData.wheelStyle=true;vehicle.userData.wheels.forEach(w=>w.children[1].material=mat(0xb24bff,.22,.85));}flashToast('FORGED WHEELS INSTALLED','Style and grip, one clean upgrade.');refreshGarage();}

// UI actions are delegated so every control remains functional after panels re-render.
initUI();
ui.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
 if(action==='play'){startAudio();$('#title-screen').remove();$('.game-hud').hidden=false;mode='play';setTargetPosition();flashToast('WELCOME TO NEON DISTRICT','Find the Central Garage to start your story.');}
 else if(action==='settings'){showSettings();}
 else if(action==='close-modal'){if(paused)paused=false;$('.modal-root').innerHTML='';}
 else if(action==='pause'){showPause();}
 else if(action==='resume'){paused=false;garageOpen=false;$('.modal-root').innerHTML='';}
 else if(action==='missions')showMissions();
 else if(action==='close-garage')closeGarage();
 else if(action==='buy-car'||action==='select-car')buyCar(e.target.closest('[data-car]')?.dataset.car);
 else if(action==='upgrade-engine')applyUpgrade('engine');
 else if(action==='upgrade-handling')applyUpgrade('handling');
 else if(action==='wheels')setWheelStyle();
});
ui.addEventListener('input',e=>{const setting=e.target.dataset.setting;if(setting==='exposure')renderer.toneMappingExposure=Number(e.target.value);if(setting==='volume'&&soundCtx){const nodes=soundCtx.destination;void nodes;}if(setting==='paint')setPaint(e.target.value);});
ui.addEventListener('change',e=>{if(e.target.dataset.setting==='shadows'){renderer.shadowMap.enabled=e.target.checked;moon.castShadow=e.target.checked;}});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'){if(garageOpen)closeGarage();else if(paused){paused=false;$('.modal-root').innerHTML='';}else if(mode==='play')showPause();}if(k==='n'&&mode==='play'){dayTime=dayTime>.5?.25:.82;flashToast(dayTime>.5?'NIGHT MODE':'DAWN MODE','The city lights respond to the hour.');}});
window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
let dragPointer=null,lastPointer=0;
renderer.domElement.addEventListener('pointerdown',e=>{dragPointer=e.pointerId;lastPointer=e.clientX;renderer.domElement.setPointerCapture(e.pointerId);});
renderer.domElement.addEventListener('pointermove',e=>{if(dragPointer!==e.pointerId||mode!=='play')return;cameraYaw+=(lastPointer-e.clientX)*.004;lastPointer=e.clientX;});
renderer.domElement.addEventListener('pointerup',()=>dragPointer=null);
window.addEventListener('wheel',e=>{cameraPitch=THREE.MathUtils.clamp(cameraPitch+e.deltaY*.0003,-.08,.42);});

