const buildingBounds=world.buildings.map(b=>({x:b.position.x,z:b.position.z,hx:b.scale.x/2+.5,hz:b.scale.z/2+.5,y:b.scale.y}));
function resolveBuildings(pos,radius=1){
 for(const b of buildingBounds){if(pos.y>b.y+1)continue;const dx=pos.x-b.x,dz=pos.z-b.z;if(Math.abs(dx)<b.hx+radius&&Math.abs(dz)<b.hz+radius){
   const px=b.hx+radius-Math.abs(dx),pz=b.hz+radius-Math.abs(dz);if(px<pz)pos.x+=Math.sign(dx||1)*px;else pos.z+=Math.sign(dz||1)*pz;
 }}
 pos.x=THREE.MathUtils.clamp(pos.x,-226,226);pos.z=THREE.MathUtils.clamp(pos.z,-226,226);
}
let jumpVelocity=0, touchX=0,touchY=0;
const touches=$('[data-stick]');
if(touches){let active=null;touches.addEventListener('pointerdown',e=>{active=e.pointerId;touches.setPointerCapture(active);moveStick(e);});touches.addEventListener('pointermove',e=>{if(active===e.pointerId)moveStick(e);});touches.addEventListener('pointerup',()=>{active=null;touchX=touchY=0;});touches.addEventListener('pointercancel',()=>{active=null;touchX=touchY=0;});
function moveStick(e){const r=touches.getBoundingClientRect();touchX=THREE.MathUtils.clamp((e.clientX-(r.left+r.width/2))/(r.width*.38),-1,1);touchY=THREE.MathUtils.clamp((e.clientY-(r.top+r.height/2))/(r.height*.38),-1,1);}}
ui.querySelectorAll('[data-key]').forEach(b=>{const key=b.dataset.key.toLowerCase();b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;});for(const ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>keys[key]=false);});
function controls(){const forward=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0)-touchY;const side=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touchX;return{forward:THREE.MathUtils.clamp(forward,-1,1),side:THREE.MathUtils.clamp(side,-1,1)};}
function updateOnFoot(dt,input){
 let f=input.forward,side=input.side;const sprint=keys.shift?1.55:1,crouch=keys.c?0.48:1;player.crouched=!!keys.c;
 const turn=new THREE.Vector3(side,0,-f);if(turn.lengthSq()>1)turn.normalize();turn.applyAxisAngle(new THREE.Vector3(0,1,0),cameraYaw);
 const desired=turn.multiplyScalar((f||side?5.4*sprint*crouch:0));player.vel.x=THREE.MathUtils.damp(player.vel.x,desired.x,11,dt);player.vel.z=THREE.MathUtils.damp(player.vel.z,desired.z,11,dt);
 const next=player.pos.clone().addScaledVector(player.vel,dt);resolveBuildings(next,.45);player.pos.x=next.x;player.pos.z=next.z;
 if(keys.space&&player.pos.y<=.01)jumpVelocity=7.1;
 jumpVelocity-=19*dt;player.pos.y=Math.max(0,player.pos.y+jumpVelocity*dt);if(player.pos.y===0)jumpVelocity=0;
 if(turn.lengthSq()>.02){const desiredHeading=Math.atan2(-turn.x,-turn.z);let delta=THREE.MathUtils.euclideanModulo(desiredHeading-player.heading+Math.PI,Math.PI*2)-Math.PI;player.heading+=delta*Math.min(1,dt*10);}
 player.walking=Math.hypot(player.vel.x,player.vel.z)>.3;character.position.copy(player.pos);character.rotation.y=player.heading;torso.scale.y=player.crouched?.78:1;
 const gait=player.walking?Math.sin(clock.elapsedTime*10*(sprint>1?1.25:1))*.58:0;legL.rotation.x=gait;legR.rotation.x=-gait;armL.rotation.x=-gait*.75;armR.rotation.x=gait*.75;
}
function updateVehicle(dt,input){
 const data=vehicle.userData,def=data.def;let v=data.speed;
 const throttle=input.forward;const brake=keys[' ']?1:0;
 const accel=(def.accel+data.upgrades.engine*4)*.58;
 v+=throttle*accel*dt;
 if(brake)v*=Math.max(0,1-5*dt);
 if(!throttle&&!brake)v*=Math.max(0,1-(.52/def.mass)*dt);
 const max=def.speed*.48+data.upgrades.engine*2.7;v=THREE.MathUtils.clamp(v,-max*.35,max);
 const steer=input.side;const ratio=Math.min(1,Math.abs(v)/4);data.heading-=steer*def.handling*(1+data.upgrades.handling*.16)*ratio*dt*(v<0?-1:1);
 const forward=new THREE.Vector3(-Math.sin(data.heading),0,-Math.cos(data.heading));
 const next=vehicle.position.clone().addScaledVector(forward,v*dt);resolveBuildings(next,def.shape==='suv'?1.2:.95);
 // Buildings absorb speed gently instead of letting the car clip through city blocks.
 if(Math.hypot(next.x-vehicle.position.x,next.z-vehicle.position.z)<Math.abs(v*dt)*.3)v*=.18;
 vehicle.position.x=next.x;vehicle.position.z=next.z;vehicle.rotation.y=data.heading;data.speed=v;speed=Math.abs(v)*5.5;
 data.wheels.forEach(w=>{w.rotation.x+=v*dt*2.4;if(w.userData.steer)w.rotation.y=steer*.28;});
 data.lamps.forEach(l=>{l.intensity=keys.s||keys[' ']?32:25;});
 player.pos.copy(vehicle.position);player.heading=data.heading;setEngineSound(v);
}
function updateTraffic(dt){
 for(const c of world.traffic){const data=c.userData;data.route=(data.route+data.aiSpeed*dt)%900;const route=data.route;let x,z,heading;
   if(route<225){x=-210+route;z=c.position.z< -30?-60:0;heading=Math.PI/2;}
   else if(route<450){x=15;z=(c.position.z< -30?-172: -112)+(route-225);heading=Math.PI;}
   else if(route<675){x=15-(route-450);z=c.position.z< -30?-172:-112;heading=-Math.PI/2;}
   else{x=-210;z=(c.position.z< -30?-172:-112)-(route-675);heading=0;}
   c.position.x=x;c.position.z=z;c.rotation.y=heading;
 }
 for(const npc of world.pedestrians){const d=npc.userData;d.phase+=dt*d.speed;npc.position.x=d.origin.x+Math.sin(d.phase)*3;npc.position.z=d.origin.z+Math.cos(d.phase*.45)*.9;npc.rotation.y=Math.sin(d.phase)*.4;}
}
function updateCamera(dt){
 const focus=vehicle?vehicle.position:player.pos;const heading=vehicle?vehicle.userData.heading:player.heading;
 const orbit=cameraYaw+(vehicle?heading:0);const distance=vehicle?10.5:7.7;const height=vehicle?3.5:(player.crouched?2.3:3.2);
 const target=new THREE.Vector3(focus.x+Math.sin(orbit)*distance*Math.cos(cameraPitch),focus.y+height+Math.sin(cameraPitch)*distance,focus.z+Math.cos(orbit)*distance*Math.cos(cameraPitch));
 camera.position.lerp(target,1-Math.exp(-4.4*dt));camera.lookAt(focus.x,focus.y+(vehicle?1:1.55),focus.z);
}
function updateMiniMap(){
 const canvas=$('.minimap canvas');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width;ctx.clearRect(0,0,w,w);ctx.fillStyle='#0a0c18';ctx.fillRect(0,0,w,w);
 ctx.save();ctx.translate(w/2,w/2);ctx.scale(1.05,1.05);ctx.translate(-player.pos.x*0.52,-player.pos.z*0.52);
 ctx.strokeStyle='#44435a';ctx.lineWidth=7;for(let p=-180;p<=180;p+=60){ctx.beginPath();ctx.moveTo(p*1.04,-240);ctx.lineTo(p*1.04,240);ctx.stroke();ctx.beginPath();ctx.moveTo(-240,p*1.04);ctx.lineTo(240,p*1.04);ctx.stroke();}
 ctx.fillStyle='#484763';world.buildings.forEach(b=>ctx.fillRect((b.position.x-b.scale.x/2)*.52,(b.position.z-b.scale.z/2)*.52,b.scale.x*.52,b.scale.z*.52));
 const target=currentTarget();if(target){ctx.beginPath();ctx.fillStyle='#57efff';ctx.shadowColor='#57efff';ctx.shadowBlur=14;ctx.arc(target.x*.52,target.z*.52,4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}
 ctx.beginPath();ctx.fillStyle='#b687ff';ctx.arc(player.pos.x*.52,player.pos.z*.52,4,0,Math.PI*2);ctx.fill();ctx.restore();
}
function updateHUD(){
 const speedEl=$('.speed'),name=$('.car-name'),gear=$('.gear');if(!speedEl)return;
 if(vehicle){speedEl.innerHTML=`${Math.round(speed).toString().padStart(3,'0')} <small>KM/H</small>`;name.textContent=vehicle.userData.def.id;gear.textContent=`${vehicle.userData.speed<0?'R':'D'} · ${vehicle.userData.def.type}`;}
 else{speedEl.innerHTML='000 <small>KM/H</small>';name.textContent='ON FOOT';gear.textContent=player.crouched?'CROUCH · QUIET MOVEMENT':keys.shift&&player.walking?'SPRINT · CITY EXPLORER':'WALK · CITY EXPLORER';}
 const target=currentTarget(),d=target?Math.hypot((vehicle?vehicle.position.x:player.pos.x)-target.x,(vehicle?vehicle.position.z:player.pos.z)-target.z):0;
 const district=$('.district');if(district){let name=districtDefs.reduce((best,a)=>Math.hypot(player.pos.x-a[0],player.pos.z-a[1])<Math.hypot(player.pos.x-best[0],player.pos.z-best[1])?a:best,districtDefs[0])[2];district.textContent=`${name} · ${dayTime>.5?'23:48':'05:32'}`;}
}
function updateLighting(dt){
 dayTime=(dayTime+dt*.00012)%1;const night=Math.max(.2,Math.sin((dayTime+.15)*Math.PI*2)*.5+.5);
 hemi.intensity=.48+night*.72;moon.intensity=.45+night*.9;ambientGlow.intensity=55+night*55;
 scene.background.set(dayTime>.5?0x080a18:0x171626);scene.fog.color.set(dayTime>.5?0x080a18:0x171626);
 mats.purple.emissiveIntensity=1.8+Math.sin(clock.elapsedTime*1.8)*.55;mats.cyan.emissiveIntensity=1.8+Math.sin(clock.elapsedTime*2.3+1)*.4;
}
function tick(){requestAnimationFrame(tick);const dt=Math.min(.04,clock.getDelta());if(mode==='play'&&!paused){
  const input=controls();if(vehicle)updateVehicle(dt,input);else updateOnFoot(dt,input);
  updateTraffic(dt);checkObjective(dt);
  if(missionIndex===6){raceTime-=dt;if(raceTime<=0){raceTime=70;raceGate=0;missionProgress=0;flashToast('RACE MISSED','The clock reset. Hit the first gate to try again.');setTargetPosition();updateMissionUI();}}
  updateCamera(dt);updateHUD();updatePrompt();
  const target=currentTarget();if(target){marker.position.set(target.x,.35+Math.sin(clock.elapsedTime*2)*.14,target.z);marker.rotation.y=clock.elapsedTime*.28;}
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('.mission-toast')?.classList.remove('show');}
 }
 updateLighting(dt);renderer.render(scene,camera);if(Math.floor(clock.elapsedTime*3)%2===0&&mode==='play')updateMiniMap();
}
setTargetPosition();updateMoney();tick();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));});

