await driveTo(38,32,200);console.log('mission',await p.locator('#mission-label').textContent(),await p.locator('#money').textContent(),await p.locator('#toast').textContent()); await driveTo(-8,11,400);let q=await get();console.log('garage approach',q.x,q.z,'prompt',await p.locator('#prompt').textContent(),'mission',await p.locator('#mission-label').textContent());await press('KeyE');console.log('modal',await p.locator('.modal-content').textContent().catch(()=>''));if(await p.locator('#upgrade-handling').count()){await p.click('#upgrade-handling');console.log('after purchase',await p.locator('.garage-balance').textContent(),await p.locator('#toast').textContent())}await b.close();
